```python
class Counted:
    eq_calls = hash_calls = lt_calls = 0
    def __init__(self, v):
        self.v = v
    def __eq__(self, other):
        Counted.eq_calls += 1
        return self.v == other.v
    def __hash__(self):
        Counted.hash_calls += 1
        return hash(self.v)
    def __lt__(self, other):
        Counted.lt_calls += 1
        return self.v < other.v
```

